def build():
    products = []
    for (name, handle, prices, sizes, raw, accords, top, mid, base, untiered, oil, unavail) in P:
        canon = CANON.get(raw) if raw else None
        if raw and not canon:
            raise SystemExit(f"missing canonical mapping for {raw!r}")
        # accord strengths: brand lists in prominence order -> 90,80,70...
        acc = [[a, max(40, 90 - i * 10)] for i, a in enumerate(accords)]
        prod = {
            "name": name,
            "url": BASE + handle,
            "conc": "edp",
            "gender": "unisex",
            "inspiredBy": canon,
            "inspiredByRaw": raw,
            "claimedAccuracy": None,
            "claimText": f"Oil concentration {oil} (brand-stated). Main accords as published by the house, in the house's order.",
            "accords": acc,
            "accordSource": "brand",
            "notesTop": top or [],
            "notesHeart": mid or [],
            "notesBase": base or [],
            "notesUntiered": untiered,
            "notesSource": "brand",
            "inStock": not unavail,
        }
        if len(prices) == 1:
            prod["priceInr"] = prices[0]
            prod["sizeMl"] = sizes[0]
        else:
            prod["variants"] = [{"priceInr": pr, "sizeMl": sz} for pr, sz in zip(prices, sizes)]
            prod["priceInr"] = min(prices)
            prod["sizeMl"] = None
        products.append(prod)
    entry = {
        "site": "https://nonameperfume.in",
        "status": "ok",
        "houseSlug": "no-name-perfume",
        "sellerSlug": "no-name-perfume-official",
        "importMode": "auto",
        "priceProvenance": "live",
        "observedAt": "2026-10-02",
        "house": {
            "name": "No Name Perfume",
            "city": None,
            "country": "India",
            "type": "indian_clone",
            "site": "https://nonameperfume.in",
            "founded": None,
            "desc": "Indian clone house (nonameperfume.in) bottling 25-30% oil-concentration EDPs in 50ml and 20ml sizes, roughly Rs.849-Rs.1299. Publishes full note pyramids, main accords and a verbatim 'Inspired by' line per scent; brand names are leetspeak-obfuscated on-site (e.g. 'M@ison Margi*la') as a trademark precaution. Researched live 2026-10-02.",
        },
        "products": products,
        "notes": "108 perfumes extracted from the site's public catalog JSON (products.json, pages 1-6) on 2026-10-02 IST. 2 non-perfume items excluded (hair oil; discovery gift set). Allure Sport and Reflection were listed unavailable at observation. 'Our Creation' scents have no inspired-by mapping.",
    }
    return entry

if __name__ == "__main__":
    entry = build()
    assert len(entry["products"]) == 108, len(entry["products"])
    mapped = sum(1 for p in entry["products"] if p["inspiredBy"])
    print(f"products=108 inspiredBy mapped={mapped} originals={108-mapped}")
    with open("/home/hatch/workspace/scentiqa/data/scrapes/no-name-perfume.json", "w") as f:
        json.dump(entry, f, ensure_ascii=False, indent=1)
    print("wrote data/scrapes/no-name-perfume.json")
